scwin.vScrenID = "ULDINS20400.xml";
scwin.cnt = 0;
scwin.prevRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : ANNA 회원관리 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS20400_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listEtcAnnaMemInfoInquiry" + "&{P}CNTR_CD=" + txb_pCNTR_CD.getValue() + "&{P}CNTR_NM=" + txb_pCNTR_NM.getValue() + "&{P}MBR_NM=" + txb_pMBR_NM.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    cmb_MBR_TP_CONTN.setDisabled(true);
};



/********************************************** 
 * 함수명   : fn_new
 * 설명       :  조회버튼 클릭시 신규등록을 위한 dataset 세팅 
 ***********************************************/
scwin.fn_new = function() {
    dts_List.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ULDINS20400_LIST_OUT";
    dts_List.reset();
    dts_List.insertRow();
    cmb_MBR_TP_CONTN.setDisabled(false);
    fn_CtrlBtn_temp("insert");
    img_CNTR_CD.setDisabled(false);
    img_CNTR_CD.src = "../img/btn_search.gif";
};


/********************************************** 
 * 함수명   : ins_process	
 * 설명       : ANNA 회원관리 저장 , 수정 한다. screenProcsTpCd 02,03
 ***********************************************/
scwin.ins_process = function(screenProcsTpCd) {
    if (screenProcsTpCd == '02') {
        // 추가

        if (!$c.stf.checkMaxLength(txb_MBR_NM, 80, "회원명")) {
            txb_MBR_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_MBR_ABBRV, 20, "회원약명")) {
            txb_MBR_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_FORN_CHRG_NM, 80, "담당자명")) {
            txb_FORN_CHRG_NM.focus();
            return false;
        }
        if (txb_CNTR_CD.getValue() == "" || txb_CNTR_CD.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드"));
            txb_CNTR_CD.focus();
            return;
        }
        if (txb_MBR_NM.getValue() == "" || txb_MBR_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "회원명"));
            txb_MBR_NM.focus();
            return;
        }
        if (!$c.stf.checkMaxLength(txb_FORN_CHRG_TEL_NO, 20, "전화번호")) {
            txb_FORN_CHRG_TEL_NO.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_FORN_CHRG_FAX_NO, 20, "팩스번호")) {
            txb_FORN_CHRG_FAX_NO.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_MBR_TP_CONTN) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "회원성격"));
            cmb_MBR_TP_CONTN.focus();
            return;
        }
        trs_save.Action = "/EtcInfoAction.do?method=registerEtcAnnaMemInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    } else if (screenProcsTpCd == '03') {
        // 수정

        if (!$c.cp.isModified(dts_List)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
        if (txb_CNTR_CD.getValue() == "" || txb_CNTR_CD.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드"));
            txb_CNTR_CD.focus();
            return;
        }
        if (txb_MBR_NM.getValue() == "" || txb_MBR_NM.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "회원명"));
            txb_MBR_NM.focus();
            return;
        }
        if ($c.stf.getObjectValue(cmb_MBR_TP_CONTN) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "회원성격"));
            cmb_MBR_TP_CONTN.focus();
            return;
        }
        if (!$c.stf.checkMaxLength(txb_MBR_NM, 80, "회원명")) {
            txb_MBR_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_MBR_ABBRV, 20, "회원약명")) {
            txb_MBR_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_FORN_CHRG_NM, 80, "담당자명")) {
            txb_FORN_CHRG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_FORN_CHRG_TEL_NO, 20, "전화번호")) {
            txb_FORN_CHRG_TEL_NO.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_FORN_CHRG_FAX_NO, 20, "팩스번호")) {
            txb_FORN_CHRG_FAX_NO.focus();
            return false;
        }
        if (!confirm('ANNA 회원관리 내용을 수정 하시겠습니까?')) {
            return;
        }
        trs_save.Action = "/EtcInfoAction.do?method=modifyEtcAnnaMemInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    } else if (screenProcsTpCd == '04') {
        // 삭제

        if (txb_CNTR_CD.getValue() == "" || txb_CNTR_CD.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드"));
            txb_CNTR_CD.focus();
            return;
        }
        if ($c.stf.getObjectValue(cmb_MBR_TP_CONTN) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "회원성격"));
            cmb_MBR_TP_CONTN.focus();
            return;
        }
        var rtn = confirm('ANNA 회원관리 내용을 삭제 하시겠습니까?');
        if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {

            //dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
            dts_ListDelete.insertRow();
            dts_ListDelete.setCellData(1, "CNTR_CD", dts_List.getCellData(dts_List.getRowPosition(), "CNTR_CD"));
            dts_ListDelete.setCellData(1, "MBR_TP_CONTN", dts_List.getCellData(dts_List.getRowPosition(), "MBR_TP_CONTN"));

            /*
            alert(dts_List.NameValue(dts_List.RowPosition,"MBR_TP_CONTN"));
            return;
            */

            trs_save.Action = "/EtcInfoAction.do?method=removeEtcAnnaMemInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
            trs_save.KeyName = "toinb_dataid4";
            trs_save.KeyValue = "JSP(I:pInput=dts_ListDelete)";
            trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
            trs_save.Post();
        }
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    fn_CtrlBtn_temp("no");
    btn_excelsave.setDisabled(true);
    btn_excelsave.src = "../img/ins/btn_excelsave_d.gif";
    img_CNTR_CD.setDisabled(true);
    img_CNTR_CD.src = "../img/btn_search_d.gif";
    txb_pCNTR_CD.focus();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    if (rowcount == 0) {
        btn_excelsave.setDisabled(true);
        btn_excelsave.src = "../img/ins/btn_excelsave_d.gif";
    } else {
        btn_excelsave.setDisabled(false);
        btn_excelsave.src = "../img/ins/btn_excelsave.gif";
    }
    scwin.cnt = rowcount;
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    scwin.cnt = 0;
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.img_pCNTR_CD_onclick = function() {
    ins_popupOpen(txb_pCNTR_CD, txb_pCNTR_NM, "ULDINS90000", "국가 코드", "435", "420");
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "ANNA 회원관리 "));
    //	ins_search();

};
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
};
scwin.btn_modify_onclick = function() {
    scwin.ins_process("03");
};
scwin.img_CNTR_CD_onclick = function() {
    ins_popupOpen(txb_CNTR_CD, txb_CNTR_NM, "ULDINS90000", "국가 코드", "435", "420");
};
scwin.btn_new_onclick = function() {
    scwin.fn_new();
};
scwin.btn_save_onclick = function() {
    scwin.ins_process("02");
};
scwin.btn_delete_onclick = function() {
    scwin.ins_process("04");
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (dts_List.getRowStatus(row) == 1) return;
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    fn_CtrlBtn_temp("update");
    img_CNTR_CD.setDisabled(true);
    img_CNTR_CD.src = "../img/btn_search_d.gif";
};
scwin.btn_excelsave_onclick = function() {
    if (scwin.cnt == 0) {
        $c.win.alert("다운로드할 자료가 없습니다");
        return;
    }
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "ANNA 회원관리", "", "2");
};
scwin.txb_pCNTR_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pCNTR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        }
    }
};
scwin.txb_pCNTR_NM_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pCNTR_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        }
    }
};
scwin.txb_pMBR_NM_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pMBR_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        }
    }
};
scwin.txb_FORN_CHRG_TEL_NO_onkeyup = function() {
    fn_DelChar(this);
};
scwin.txb_FORN_CHRG_FAX_NO_onkeyup = function() {
    fn_DelChar(this);
};
scwin.txb_FORN_CHRG_NM_onkeyup = function() {
    fn_DelChar(this);
};
scwin.txb_MBR_NM_onkeyup = function() {
    fn_DelChar(this);
};
scwin.txb_ENCRYP_FORN_CHRG_EMAIL_onkeyup = function() {
    fn_DelChar4(this);
};
